DELETE FROM AGENCYRECEIPTMASTER WHERE AGENCYRECEIPTMASTER.ARECEIPT_yearid = @YEARID AND AGENCYRECEIPTMASTER.ARECEIPT_no <= (SELECT MAX(AGENCYRECEIPTMASTER.ARECEIPT_no) FROM AGENCYRECEIPTMASTER WHERE AGENCYRECEIPTMASTER.ARECEIPT_yearid = @SELECTEDYEARID)

INSERT INTO AGENCYRECEIPTMASTER
SELECT AGENCYRECEIPTMASTER.ARECEIPT_NO, NREGISTERMASTER.REGISTER_ID, Areceipt_initials, Areceipt_date, NSELLERLEDGERS.ACC_ID, NLEDGERS.ACC_ID, Areceipt_BANKNAME , 
Areceipt_total, Areceipt_CHQNO, Areceipt_remarks, Areceipt_BILLREMARKS, Areceipt_OURREMARKS, Areceipt_inwords, Areceipt_CHECKPDC, Areceipt_RECODATE, 
Areceipt_SMSSEND, @CMPID, 0 AS LOCATIONID, Areceipt_userid, @YEARID, 0 AS [TRANSFER], Areceipt_created, Areceipt_SPECIALREMARKS, Areceipt_SENDWHATSAPP, Areceipt_CHQDATE, 
ARECEIPT_COMPLAINT, ARECEIPT_COMPLAINTBY, ARECEIPT_COMPLAINTDATE, ARECEIPT_HOLDINTCALC
FROM AGENCYRECEIPTMASTER INNER JOIN 
LEDGERS ON AGENCYRECEIPTMASTER.ARECEIPT_LEDGERID = LEDGERS.ACC_ID INNER JOIN LEDGERS AS NLEDGERS ON LEDGERS.ACC_CMPNAME = NLEDGERS.ACC_CMPNAME AND NLEDGERS.Acc_yearid = @YEARID LEFT OUTER JOIN
LEDGERS AS SELLERLEDGERS ON AGENCYRECEIPTMASTER.ARECEIPT_SELLERID= SELLERLEDGERS.ACC_ID LEFT OUTER JOIN LEDGERS AS NSELLERLEDGERS ON SELLERLEDGERS.ACC_CMPNAME = NSELLERLEDGERS.ACC_CMPNAME AND NSELLERLEDGERS.Acc_yearid = @YEARID LEFT OUTER JOIN
REGISTERMASTER ON AGENCYRECEIPTMASTER.Areceipt_registerid= REGISTERMASTER.REGISTER_ID LEFT OUTER JOIN REGISTERMASTER AS NREGISTERMASTER ON REGISTERMASTER.register_name = NREGISTERMASTER.register_name AND NREGISTERMASTER.register_yearid = @YEARID 
WHERE AGENCYRECEIPTMASTER.ARECEIPT_YEARID = @SELECTEDYEARID AND LEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ BUYER ]' AND SELLERLEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ SELLER ]' 
ORDER BY AGENCYRECEIPTMASTER.ARECEIPT_NO DESC



DELETE FROM AGENCYRECEIPTMASTER_DESC WHERE AGENCYRECEIPTMASTER_DESC.ARECEIPT_yearid = @YEARID AND AGENCYRECEIPTMASTER_DESC.ARECEIPT_no <= (SELECT MAX(AGENCYRECEIPTMASTER_DESC.ARECEIPT_no) FROM AGENCYRECEIPTMASTER_DESC WHERE AGENCYRECEIPTMASTER_DESC.ARECEIPT_yearid = @SELECTEDYEARID)

INSERT INTO AGENCYRECEIPTMASTER_DESC
SELECT AGENCYRECEIPTMASTER.ARECEIPT_NO, NREGISTERMASTER.REGISTER_ID, AGENCYRECEIPTMASTER.Areceipt_initials, ARECEIPT_GRIDSRNO, ARECEIPT_PAYTYPE, ARECEIPT_BILLINITIALS, 
ARECEIPT_GRIDREMARKS, AGENCYRECEIPTMASTER_DESC.ARECEIPT_AMT, AGENCYRECEIPTMASTER_DESC.ARECEIPT_AMTPAID, AGENCYRECEIPTMASTER_DESC.ARECEIPT_EXTRAAMT, AGENCYRECEIPTMASTER_DESC.ARECEIPT_RETURN, 
AGENCYRECEIPTMASTER_DESC.ARECEIPT_BALANCE, @CMPID, 0 AS LOCATIONID, AGENCYRECEIPTMASTER_DESC.ARECEIPT_USERID, @YEARID, 0 AS [TRANSFER], AGENCYRECEIPTMASTER_DESC.Areceipt_created
FROM AGENCYRECEIPTMASTER_DESC INNER JOIN AGENCYRECEIPTMASTER ON AGENCYRECEIPTMASTER_DESC.ARECEIPT_no = AGENCYRECEIPTMASTER.ARECEIPT_NO AND AGENCYRECEIPTMASTER_DESC.ARECEIPT_yearid = AGENCYRECEIPTMASTER.ARECEIPT_YEARID INNER JOIN 
LEDGERS ON AGENCYRECEIPTMASTER.ARECEIPT_LEDGERID = LEDGERS.ACC_ID INNER JOIN LEDGERS AS NLEDGERS ON LEDGERS.ACC_CMPNAME = NLEDGERS.ACC_CMPNAME AND NLEDGERS.Acc_yearid = @YEARID LEFT OUTER JOIN
LEDGERS AS SELLERLEDGERS ON AGENCYRECEIPTMASTER.Areceipt_sellerid = SELLERLEDGERS.ACC_ID LEFT OUTER JOIN LEDGERS AS NSELLERLEDGERS ON SELLERLEDGERS.ACC_CMPNAME = NSELLERLEDGERS.ACC_CMPNAME AND NSELLERLEDGERS.Acc_yearid = @YEARID LEFT OUTER JOIN
REGISTERMASTER ON AGENCYRECEIPTMASTER.Areceipt_registerid= REGISTERMASTER.REGISTER_ID LEFT OUTER JOIN REGISTERMASTER AS NREGISTERMASTER ON REGISTERMASTER.register_name = NREGISTERMASTER.register_name AND NREGISTERMASTER.register_yearid = @YEARID 

WHERE AGENCYRECEIPTMASTER.ARECEIPT_YEARID = @SELECTEDYEARID AND LEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ BUYER ]' AND SELLERLEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ SELLER ]' 
ORDER BY AGENCYRECEIPTMASTER.ARECEIPT_NO DESC



