DELETE FROM AGENCYSALEORDER WHERE AGENCYSALEORDER.ASO_yearid = @YEARID AND AGENCYSALEORDER.ASO_no <= (SELECT MAX(AGENCYSALEORDER.ASO_no) FROM AGENCYSALEORDER WHERE AGENCYSALEORDER.ASO_yearid = @SELECTEDYEARID)


INSERT INTO AGENCYSALEORDER
SELECT ASO_NO, ASO_DATE, NLEDGERS.ACC_ID, 0 AS HASTEID, 0 AS AGENTID, ASO_PONO, ASO_DUEDATE, 0 AS TRANSID, 0 AS TRANSID1, NCITYMASTER.CITY_ID AS CITYID,
ASO_REFNO, ASO_RISK, ASO_CONSIGNOR, ASO_CONSIGNEE, NPACKINGLEDGERS.ACC_ID, 0 AS CURRID, ASO_TOTALQTY, ASO_TOTALMTRS, ASO_TOTALBALES, ASO_TOTALAMT, 
ASO_DISPER, ASO_DISAMT, ASO_PFPER, ASO_PFAMT, ASO_TESTCHGS, ASO_NETT, ASO_EXCISEID, ASO_EXCISEAMT, ASO_EDUCESSAMT, ASO_HSECESSAMT, ASO_SUBTOTAL, 0 AS TAXID, 0 AS TAXAMT, 
0 AS ADDTAXID, 0 AS ADDTAXAMT, 0 AS FRPER, 0 FREIGHT, 0 AS OCTID, 0 AS OCTAMT, 0 AS INSAMT, ASO_ROUNDOFF, ASO_GRANDTOTAL, ASO_INWORDS, ASO_remarks, ASO_NOTE, ASO_TNC,
0 AS MISCPER, ASO_DISCRATE, ASO_DISCLOT, ASO_DISCDEALER, ASO_KATAI, ASO_CD, ASO_ADAT, ASO_DAYS, ASO_INT, ASO_DONE, ASO_ADVANCE, ASO_BALANCE, 0 AS SALESMANID, 0 AS PACKINGTYPEID,
ASO_SMSSEND, ASO_FORWARD, ASO_SAMPLE, @CMPID, 0 AS LOCATIONID, ASO_USERID, @YEARID, 0 AS [TRANSFER], ASO_CREATED, ASO_MODIFIED, ASO_MODIFIEDBY, ASO_SENDWHATSAPP, 
NFROMCITYMASTER.CITY_ID, ASO_VERIFIED, ASO_ORDERON
FROM AGENCYSALEORDER INNER JOIN LEDGERS ON AGENCYSALEORDER.ASO_LEDGERID = LEDGERS.ACC_ID INNER JOIN LEDGERS AS NLEDGERS ON LEDGERS.ACC_CMPNAME = NLEDGERS.ACC_CMPNAME AND NLEDGERS.Acc_yearid = @YEARID LEFT OUTER JOIN
CITYMASTER ON AGENCYSALEORDER.ASO_CITYID = CITYMASTER.CITY_ID LEFT OUTER JOIN CITYMASTER AS NCITYMASTER ON CITYMASTER.CITY_NAME = NCITYMASTER.CITY_NAME AND NCITYMASTER.city_yearid = @YEARID LEFT OUTER JOIN
CITYMASTER AS FROMCITYMASTER ON AGENCYSALEORDER.ASO_FROMCITYID = FROMCITYMASTER.CITY_ID LEFT OUTER JOIN CITYMASTER AS NFROMCITYMASTER ON FROMCITYMASTER.CITY_NAME = NFROMCITYMASTER.CITY_NAME AND NFROMCITYMASTER.city_yearid = @YEARID LEFT OUTER JOIN
LEDGERS AS PACKINGLEDGERS ON AGENCYSALEORDER.ASO_PACKINGID = PACKINGLEDGERS.ACC_ID LEFT OUTER JOIN LEDGERS AS NPACKINGLEDGERS ON PACKINGLEDGERS.ACC_CMPNAME = NPACKINGLEDGERS.ACC_CMPNAME AND NPACKINGLEDGERS.Acc_yearid = @YEARID
WHERE AGENCYSALEORDER.ASO_YEARID = @SELECTEDYEARID AND LEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ BUYER ]' AND PACKINGLEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ SELLER ]' AND AGENCYSALEORDER.ASO_NO NOT IN (SELECT ASO_NO FROM AGENCYSALEORDER WHERE ASO_YEARID = @YEARID)
ORDER BY AGENCYSALEORDER.ASO_NO DESC



DELETE FROM AGENCYSALEORDER_DESC WHERE AGENCYSALEORDER_DESC.ASO_yearid = @YEARID AND AGENCYSALEORDER_DESC.ASO_no <= (SELECT MAX(AGENCYSALEORDER_DESC.ASO_no) FROM AGENCYSALEORDER_DESC WHERE AGENCYSALEORDER_DESC.ASO_yearid = @SELECTEDYEARID)

INSERT INTO AGENCYSALEORDER_DESC
SELECT AGENCYSALEORDER.ASO_NO, ASO_GRIDSRNO, NITEMMASTER.ITEM_ID,  0 AS QUALITYID, 0 AS DESIGNID, ASO_GRIDREMARKS, 0 AS COLORID,
ASO_PARTYPONO, ASO_QTY, NUNITMASTER.UNIT_ID, ASO_CUT, ASO_MTRS, ASO_RATE, AGENCYSALEORDER_DESC.ASO_PER, AGENCYSALEORDER_DESC.ASO_AMOUNT, 
ASO_RECDQTY, ASO_RECDMTRS, ASO_CLOSED, ASO_CLOSEDDATE, ASO_CLOSEDREASON, AGENCYSALEORDER_DESC.ASO_DONE, AGENCYSALEORDER_DESC.ASO_SAMPLEDONE, @CMPID, 0 AS LOCATIONID, 
AGENCYSALEORDER_DESC.ASO_USERID, @YEARID, 0 AS [TRANSFER], AGENCYSALEORDER_DESC.ASO_CREATED, AGENCYSALEORDER_DESC.ASO_MODIFIED, AGENCYSALEORDER_DESC.ASO_MODIFIEDBY
FROM AGENCYSALEORDER_DESC INNER JOIN AGENCYSALEORDER ON AGENCYSALEORDER_DESC.ASO_no = AGENCYSALEORDER.ASO_NO AND AGENCYSALEORDER_DESC.ASO_yearid = AGENCYSALEORDER.ASO_YEARID INNER JOIN 
LEDGERS ON AGENCYSALEORDER.ASO_LEDGERID = LEDGERS.ACC_ID INNER JOIN LEDGERS AS NLEDGERS ON LEDGERS.ACC_CMPNAME = NLEDGERS.ACC_CMPNAME AND NLEDGERS.Acc_yearid = @YEARID LEFT OUTER JOIN
ITEMMASTER ON AGENCYSALEORDER_DESC.ASO_ITEMID = ITEMMASTER.ITEM_ID LEFT OUTER JOIN ITEMMASTER AS NITEMMASTER ON ITEMMASTER.ITEM_NAME = NITEMMASTER.ITEM_NAME AND NITEMMASTER.ITEM_yearid = @YEARID LEFT OUTER JOIN
LEDGERS AS PACKINGLEDGERS ON AGENCYSALEORDER.ASO_PACKINGID = PACKINGLEDGERS.ACC_ID LEFT OUTER JOIN LEDGERS AS NPACKINGLEDGERS ON PACKINGLEDGERS.ACC_CMPNAME = NPACKINGLEDGERS.ACC_CMPNAME AND NPACKINGLEDGERS.Acc_yearid = @YEARID LEFT OUTER JOIN
UNITMASTER ON AGENCYSALEORDER_DESC.ASO_UNITID = UNITMASTER.UNIT_ID LEFT OUTER JOIN UNITMASTER AS NUNITMASTER ON UNITMASTER.UNIT_NAME = NUNITMASTER.UNIT_NAME AND NUNITMASTER.UNIT_yearid = @YEARID
WHERE AGENCYSALEORDER.ASO_YEARID = @SELECTEDYEARID AND LEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ BUYER ]' AND PACKINGLEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ SELLER ]' 
ORDER BY AGENCYSALEORDER.ASO_NO DESC

