DELETE FROM AGENCYSALERETURN WHERE AGENCYSALERETURN.ASALRET_yearid = @YEARID AND AGENCYSALERETURN.ASALRET_no <= (SELECT MAX(AGENCYSALERETURN.ASALRET_no) FROM AGENCYSALERETURN WHERE AGENCYSALERETURN.ASALRET_yearid = @SELECTEDYEARID)


INSERT INTO AGENCYSALERETURN
SELECT ASALRET_NO, ASALRET_DATE, NLEDGERS.ACC_ID, NDELIVERYATLEDGERS.ACC_ID, ASALRET_CHALLANNO, ASALRET_CHALLANDATE, ASALRET_ACTUALINVNO, ASALRET_ACTUALINVDATE,
ASALRET_INVOICENO, ASALRET_INVOICEDATE, ASALRET_INVOICETYPE, ASALRET_INVOICEINITIALS, ASALRET_PARTYREFNO, ASALRET_SRCHNO, NTRANSLEDGERS.ACC_ID, ASALRET_LRNO, ASALRET_LRDATE, 
0 AS AGENTID, ASALRET_EWAYBILLNO, ASALRET_TOTALWT, ASALRET_TOTALQTY, ASALRET_TOTALMTRS, ASALRET_TOTALAMT, ASALRET_MANUALGST, ASALRET_CGSTPER, ASALRET_TOTALCGSTAMT, ASALRET_SGSTPER, ASALRET_TOTALSGSTAMT,
ASALRET_IGSTPER, ASALRET_TOTALIGSTAMT, ASALRET_AMOUNT, ASALRET_CHARGES, ASALRET_SUBTOTAL, ASALRET_TOTALWITHGST, ASALRET_APPLYTCS, ASALRET_TCSPER, ASALRET_TCSAMT,
ASALRET_ROUNDOFF, ASALRET_GRANDTOTAL, ASALRET_INWORDS, ASALRET_remarks, ASALRET_BILLREMARKS, ASALRET_DONE, ASALRET_PRINTINITIALS, ASALRET_IRNNO, ASALRET_ACKNO, ASALRET_ACKDATE, 
ASALRET_QRCODE, @CMPID, 0 AS LOCATIONID, ASALRET_USERID, @YEARID, 0 AS [TRANSFER], ASALRET_CREATED, ASALRET_MODIFIED, ASALRET_MODIFIEDBY, ASALRET_SPECIALREMARKS, ASALRET_CD, 
ASALRET_SENDWHATSAPP, ASALRET_NOOFBALES, ASALRET_EXPORTGST, 0 AS COSTCENTRE, ASALRET_MANUALROUNDOFF, NFROMCITYMASTER.CITY_ID, NTOCITYMASTER.CITY_ID, ASALRET_COMPLAINT, ASALRET_COMPLAINTBY, ASALRET_COMPLAINTDATE, ASALRET_HOLDINTCALC
FROM AGENCYSALERETURN INNER JOIN LEDGERS ON AGENCYSALERETURN.ASALRET_LEDGERID = LEDGERS.ACC_ID INNER JOIN LEDGERS AS NLEDGERS ON LEDGERS.ACC_CMPNAME = NLEDGERS.ACC_CMPNAME AND NLEDGERS.Acc_yearid = @YEARID LEFT OUTER JOIN
CITYMASTER AS FROMCITYMASTER ON AGENCYSALERETURN.ASALRET_FROMCITYID = FROMCITYMASTER.CITY_ID LEFT OUTER JOIN CITYMASTER AS NFROMCITYMASTER ON FROMCITYMASTER.CITY_NAME = NFROMCITYMASTER.CITY_NAME AND NFROMCITYMASTER.city_yearid = @YEARID LEFT OUTER JOIN
CITYMASTER AS TOCITYMASTER ON AGENCYSALERETURN.ASALRET_TOCITYID = TOCITYMASTER.CITY_ID LEFT OUTER JOIN CITYMASTER AS NTOCITYMASTER ON TOCITYMASTER.CITY_NAME = NTOCITYMASTER.CITY_NAME AND NTOCITYMASTER.city_yearid = @YEARID LEFT OUTER JOIN
LEDGERS AS DELIVERYATLEDGERS ON AGENCYSALERETURN.ASALRET_DELIVERYATID = DELIVERYATLEDGERS.ACC_ID LEFT OUTER JOIN LEDGERS AS NDELIVERYATLEDGERS ON DELIVERYATLEDGERS.ACC_CMPNAME = NDELIVERYATLEDGERS.ACC_CMPNAME AND NDELIVERYATLEDGERS.Acc_yearid = @YEARID LEFT OUTER JOIN
LEDGERS AS TRANSLEDGERS ON AGENCYSALERETURN.ASALRET_TRANSID = TRANSLEDGERS.ACC_ID LEFT OUTER JOIN LEDGERS AS NTRANSLEDGERS ON TRANSLEDGERS.ACC_CMPNAME = NTRANSLEDGERS.ACC_CMPNAME AND NTRANSLEDGERS.Acc_yearid = @YEARID
WHERE AGENCYSALERETURN.ASALRET_YEARID = @SELECTEDYEARID AND LEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ BUYER ]' AND DELIVERYATLEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ SELLER ]' AND AGENCYSALERETURN.ASALRET_NO NOT IN (SELECT ASALRET_NO FROM AGENCYSALERETURN WHERE ASALRET_YEARID = @YEARID)
ORDER BY AGENCYSALERETURN.ASALRET_NO DESC


