DELETE FROM AGENCYSALERETURN_CHGS WHERE AGENCYSALERETURN_CHGS.ASALRET_yearid = @YEARID AND AGENCYSALERETURN_CHGS.ASALRET_no <= (SELECT MAX(AGENCYSALERETURN_CHGS.ASALRET_no) FROM AGENCYSALERETURN_CHGS WHERE AGENCYSALERETURN_CHGS.ASALRET_yearid = @SELECTEDYEARID)

