LEDGERS AS CHARGESLEDGERS ON AGENCYSALERETURN_CHGS.ASALRET_CHARGESID = CHARGESLEDGERS.ACC_ID LEFT OUTER JOIN LEDGERS AS NCHARGESLEDGERS ON CHARGESLEDGERS.ACC_CMPNAME = NCHARGESLEDGERS.ACC_CMPNAME AND NCHARGESLEDGERS.Acc_yearid = @YEARID LEFT OUTER JOIN
LEDGERS AS DELIVERYATLEDGERS ON AGENCYSALERETURN.ASALRET_DELIVERYATID = DELIVERYATLEDGERS.ACC_ID LEFT OUTER JOIN LEDGERS AS NDELIVERYATLEDGERS ON DELIVERYATLEDGERS.ACC_CMPNAME = NDELIVERYATLEDGERS.ACC_CMPNAME AND NDELIVERYATLEDGERS.Acc_yearid = @YEARID 
WHERE AGENCYSALERETURN.ASALRET_YEARID = @SELECTEDYEARID AND LEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ BUYER ]' AND DELIVERYATLEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ SELLER ]' 
