DELETE FROM AGENCYSALERETURN_DESC WHERE AGENCYSALERETURN_DESC.ASALRET_yearid = @YEARID AND AGENCYSALERETURN_DESC.ASALRET_no <= (SELECT MAX(AGENCYSALERETURN_DESC.ASALRET_no) FROM AGENCYSALERETURN_DESC WHERE AGENCYSALERETURN_DESC.ASALRET_yearid = @SELECTEDYEARID)

