ASALRET_AQTY, ASALRET_AFOLDPER, ASALRET_BALENO, ASALRET_CUT, ASALRET_WT, ASALRET_QTY, NUNITMASTER.UNIT_ID, ASALRET_MTRS, ASALRET_RATE, AGENCYSALERETURN_DESC.ASALRET_PER, AGENCYSALERETURN_DESC.ASALRET_AMT, 
