@CMPID, 0 AS LOCATIONID, AGENCYSALERETURN_DESC.ASALRET_USERID, @YEARID, 0 AS [TRANSFER], AGENCYSALERETURN_DESC.ASALRET_CREATED, AGENCYSALERETURN_DESC.ASALRET_MODIFIED, AGENCYSALERETURN_DESC.ASALRET_MODIFIEDBY
FROM AGENCYSALERETURN_DESC INNER JOIN AGENCYSALERETURN ON AGENCYSALERETURN_DESC.ASALRET_no = AGENCYSALERETURN.ASALRET_NO AND AGENCYSALERETURN_DESC.ASALRET_yearid = AGENCYSALERETURN.ASALRET_YEARID INNER JOIN 
LEDGERS ON AGENCYSALERETURN.ASALRET_LEDGERID = LEDGERS.ACC_ID INNER JOIN LEDGERS AS NLEDGERS ON LEDGERS.ACC_CMPNAME = NLEDGERS.ACC_CMPNAME AND NLEDGERS.Acc_yearid = @YEARID LEFT OUTER JOIN
ITEMMASTER ON AGENCYSALERETURN_DESC.ASALRET_ITEMID = ITEMMASTER.ITEM_ID LEFT OUTER JOIN ITEMMASTER AS NITEMMASTER ON ITEMMASTER.ITEM_NAME = NITEMMASTER.ITEM_NAME AND NITEMMASTER.ITEM_yearid = @YEARID LEFT OUTER JOIN
LEDGERS AS DELIVERYATLEDGERS ON AGENCYSALERETURN.ASALRET_DELIVERYATID = DELIVERYATLEDGERS.ACC_ID LEFT OUTER JOIN LEDGERS AS NDELIVERYATLEDGERS ON DELIVERYATLEDGERS.ACC_CMPNAME = NDELIVERYATLEDGERS.ACC_CMPNAME AND NDELIVERYATLEDGERS.Acc_yearid = @YEARID  LEFT OUTER JOIN
HSNMASTER ON AGENCYSALERETURN_DESC.ASALRET_HSNCODEID = HSNMASTER.HSN_ID LEFT OUTER JOIN HSNMASTER AS NHSNMASTER ON HSNMASTER.HSN_CODE = NHSNMASTER.HSN_CODE AND NHSNMASTER.HSN_yearid = @YEARID LEFT OUTER JOIN
UNITMASTER ON AGENCYSALERETURN_DESC.ASALRET_QTYUNITID = UNITMASTER.UNIT_ID LEFT OUTER JOIN UNITMASTER AS NUNITMASTER ON UNITMASTER.UNIT_NAME = NUNITMASTER.UNIT_NAME AND NUNITMASTER.UNIT_yearid = @YEARID LEFT OUTER JOIN
PIECETYPEMASTER ON AGENCYSALERETURN_DESC.ASALRET_PIECETYPEID = PIECETYPEMASTER.PIECETYPE_id LEFT OUTER JOIN PIECETYPEMASTER AS NPIECETYPEMASTER ON PIECETYPEMASTER.PIECETYPE_name = NPIECETYPEMASTER.PIECETYPE_name AND NPIECETYPEMASTER.PIECETYPE_yearid = @YEARID
WHERE AGENCYSALERETURN.ASALRET_YEARID = @SELECTEDYEARID AND LEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ BUYER ]' AND DELIVERYATLEDGERS.ACC_CMPNAME <> 'ABHEE FABRICS LLP [ SELLER ]' 
ORDER BY AGENCYSALERETURN.ASALRET_NO DESC


-- **************** END OF AGENCYSALERETURN **********************


